"""Turns plain resume text into a light structure (header, contact, sections, items)."""
import re

from .lang_data import BULLET_RE, EMAIL_RE, HEADING_LOOKUP, PHONE_RE, URL_RE


def _normalise_heading(line: str) -> str:
    """Lower-case a candidate heading and strip decoration such as colons or bullets."""
    line = BULLET_RE.sub("", line)
    return re.sub(r"[\s:：\-–—_=#*|]+$", "", line.strip()).strip(" :：#*").lower()


def classify_heading(line: str) -> tuple[str | None, str | None]:
    """Return (section_key, inline_text) if the line is a section heading, else (None, None).

    Supports "Skills: Python, AWS" style headings with inline content.
    """
    stripped = line.strip()
    if not stripped or len(stripped) > 120:
        return None, None
    norm = _normalise_heading(stripped)
    if norm in HEADING_LOOKUP and len(stripped) <= 45:
        return HEADING_LOOKUP[norm], None
    m = re.match(r"^([^:：]{2,40})[:：]\s*(.+)$", stripped)
    if m and _normalise_heading(m.group(1)) in HEADING_LOOKUP:
        return HEADING_LOOKUP[_normalise_heading(m.group(1))], m.group(2).strip()
    letters = re.sub(r"[^A-Za-z]", "", stripped)
    if (letters and stripped.upper() == stripped and len(stripped) <= 35 and len(stripped.split()) <= 4
            and not re.search(r"\d|@", stripped) and len(letters) >= 4):
        return "other", None
    return None, None


def _is_contact_line(line: str) -> bool:
    """True for lines that carry contact details (email, phone, links or separators)."""
    return bool(EMAIL_RE.search(line) or PHONE_RE.search(line) or URL_RE.search(line)) or line.count("|") >= 1


def parse_resume(text: str) -> dict:
    """Parse resume text into {name, headline, contact, contact_line, sections}."""
    lines = [ln.strip() for ln in text.split("\n")]
    header: list[str] = []
    sections: list[dict] = []
    current: dict | None = None

    for line in lines:
        if not line:
            continue
        key, inline = classify_heading(line)
        if key == "other" and current is None and not header:
            key = None  # an all-caps first line is the candidate's name, not a heading
        if key:
            heading = line.split(":")[0].split("：")[0].strip() if inline else line.rstrip(":： ")
            current = {"key": key, "heading": heading, "items": []}
            sections.append(current)
            if inline:
                current["items"].append({"type": "text", "text": inline})
            continue
        if current is None:
            header.append(line)
            continue
        if BULLET_RE.match(line):
            current["items"].append({"type": "bullet", "text": BULLET_RE.sub("", line).strip()})
        else:
            current["items"].append({"type": "text", "text": line})

    name, headline, contact_parts = "", "", []
    for line in header:
        if not name and not _is_contact_line(line) and len(line) <= 60:
            name = line
        elif name and not headline and not _is_contact_line(line) and len(line) <= 100:
            headline = line
        else:
            contact_parts.append(line)

    # Without any recognised headings, keep the body as a single generic section.
    if not sections and len(header) > 3:
        body = header[2:]
        sections = [{"key": "other", "heading": "", "items": [
            {"type": "bullet" if BULLET_RE.match(l) else "text", "text": BULLET_RE.sub("", l)} for l in body]}]
        contact_parts = []

    joined = " ".join(contact_parts + header[:3])
    contact = {
        "email": (EMAIL_RE.search(joined) or [None])[0],
        "phone": (PHONE_RE.search(joined) or [None])[0],
        "links": URL_RE.findall(joined),
    }
    return {
        "name": name,
        "headline": headline,
        "contact": contact,
        "contact_line": " | ".join(p.strip(" |") for p in contact_parts if p.strip(" |")),
        "sections": sections,
    }


def structure_to_text(doc: dict) -> str:
    """Render a parsed structure back to ATS-friendly plain text."""
    out = [doc.get("name", "")]
    if doc.get("headline"):
        out.append(doc["headline"])
    if doc.get("contact_line"):
        out.append(doc["contact_line"])
    for sec in doc.get("sections", []):
        out.append("")
        if sec.get("heading"):
            out.append(sec["heading"].upper() if sec["heading"].isascii() else sec["heading"])
        for item in sec["items"]:
            out.append(f"- {item['text']}" if item["type"] == "bullet" else item["text"])
    return "\n".join(out).strip()
